-- Y'a du peuple ? — Courbes d'affluence par restaurant (relevées sur Google Maps le 11/11/2026)
-- À valider par Alexis avant exécution. Ne supprime aucune donnée existante.
-- 1. Table popular_times : 168 valeurs par resto (7 jours x 24 h), 0-100 % du pic de la semaine.
--    Index = jour*24 + heure (+1 en SQL), jour 0 = dimanche (comme Google). NULL = pas de donnée.
--    Comme sur Google, 0 h-4 h d'un jour = fin de soirée de ce jour-là.
-- 2. popular_level(resto) : niveau de l'heure actuelle d'après la courbe
--    (< 25 % calme, < 50 % un peu de monde, < 75 % animé, sinon y'a du peuple). Sans courbe : ancienne règle.
-- 3. get_service_status utilise popular_level au lieu de theory_level (signalements et estimations
--    habituelles restent prioritaires, rien d'autre ne change).

create table if not exists public.popular_times (
  establishment_id uuid primary key references public.establishments(id) on delete cascade,
  profile smallint[] not null check (array_length(profile, 1) = 168),
  source text not null default 'google_maps',
  updated_at timestamptz not null default now()
);
alter table public.popular_times enable row level security;
drop policy if exists "popular_times lecture publique" on public.popular_times;
create policy "popular_times lecture publique" on public.popular_times for select using (true);
grant select on public.popular_times to anon, authenticated;

