on conflict (establishment_id) do update set profile = excluded.profile, updated_at = now();

create or replace function public.popular_level(p_establishment uuid)
returns text language plpgsql stable security definer set search_path to ''
as $$
declare
  t timestamp := now() at time zone 'Europe/Paris';
  d int := extract(dow from t)::int;
  h int := extract(hour from t)::int;
  prof smallint[];
  v smallint;
begin
  select pt.profile into prof from public.popular_times pt where pt.establishment_id = p_establishment;
  if prof is null then return public.theory_level(); end if;
  if h < 5 then d := (d + 6) % 7; end if; -- après minuit : fin de soirée de la veille
  v := prof[d * 24 + h + 1];
  if v is null or v = 0 then return null; end if; -- fermé / pas de donnée
  return case when v < 25 then 'calme' when v < 50 then 'modere' when v < 75 then 'frequente' else 'tres_frequente' end;
end;
$$;
grant execute on function public.popular_level(uuid) to anon, authenticated;

do $$
declare def text;
begin
  select pg_get_functiondef('public.get_service_status(uuid, text)'::regprocedure) into def;
  if position('public.theory_level()' in def) = 0 then
    raise exception 'get_service_status ne contient pas theory_level : rien modifié';
  end if;
  execute replace(def, 'public.theory_level()', 'public.popular_level(p_establishment)');
end $$;
